/**
 * Generates TypeScript bindings for every Newton policy pack in this
 * monorepo. Iterates the AVS-side pack directories at the repo root
 * (`<pack>/{wasm_args_schema.json, secrets_schema.json, params_schema.json,
 * policy_metadata.json}`) and emits per-package bindings into
 * `packages/policy-pack-<name>/src/`.
 *
 * Run with `pnpm gen:bindings` (from the repo root).
 *
 * The generated `src/*` files all carry an AUTO-GENERATED banner — never
 * hand-edit them. The per-package `package.json`, `tsconfig.json`, and
 * `tsup.config.ts` are scaffolded once and not overwritten on regen, so
 * pack maintainers can hand-tune them (e.g. add a custom prepare-query
 * dep) without losing their work.
 *
 * The umbrella package (`packages/policy-packs`, `@newton-xyz/policy-packs`)
 * is the only publishing package — the per-pack packages are `private` and
 * the umbrella bundles them. Its per-pack wiring (`src/<name>.ts` modules,
 * `src/index.ts` namespace exports, the `tsup.config.ts` entry list, and
 * the `package.json` `exports` subpaths + workspace devDependencies) is
 * regenerated from the discovered pack list on every run (see
 * `emitUmbrella`), so adding a pack directory is the only manual step,
 * plus `pnpm install` for the lockfile.
 *
 * History: retargeted from PR #25's `sdk/scripts/generate-packs.ts` (Alec
 * Savvy) per NEWT-1457. Original emitted into a single `sdk/src/packs/`
 * subtree; this version emits into one workspace per pack so each
 * publishes independently as `@newton-xyz/policy-pack-<name>`.
 */

import { existsSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { jsonSchemaToZod } from "json-schema-to-zod";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = path.resolve(__dirname, "..");
const PACKAGES_DIR = path.join(REPO_ROOT, "packages");
// The provider trust-data package: holds the hand-authored KNOWN_PACK_IDS
// registry (parsed below for the drift check) and receives the generated
// AUDITED_POLICY_DATA map. Replaces the retired policy-pack-shared as the codegen's
// registry/provenance target.
const REGISTRY_PACKAGE_DIR = path.join(PACKAGES_DIR, "policy-pack-registry");
// The umbrella package: bundles every (private) per-pack package and is the
// only package that publishes. Its per-pack wiring is codegen-owned (see
// emitUmbrella below).
const UMBRELLA_PACKAGE_DIR = path.join(PACKAGES_DIR, "policy-packs");

const SCHEMA_FILES = [
	"wasm_args_schema.json",
	"secrets_schema.json",
	"params_schema.json",
] as const;

const BANNER = `// AUTO-GENERATED by scripts/generate-bindings.ts - DO NOT EDIT.
// Source: AVS-side artifacts in this repo (run \`pnpm gen:bindings\` to regenerate).
`;

/**
 * Resolve the `@newton-xyz/policy-core` peer-dep range to emit into per-pack
 * `package.json` files, from an AUTHORITATIVE in-repo declared source: the
 * repo-root `package.json`'s `devDependencies["@newton-xyz/policy-core"]`.
 *
 * policy-core lives in a DIFFERENT repo (the vaultkit monorepo) and installs
 * from npm here, so there is no in-workspace package.json to read its version
 * from. Deliberately NOT read from `node_modules/@newton-xyz/policy-core`: that
 * is installer-cache state, not a release contract - a stale or absent install
 * would silently emit a wrong peer range that only surfaces post-publish as an
 * incompatible core/packs/vaultkit combo. The checked-in root devDep IS the
 * declared contract.
 *
 * The emitted PEER range is NOT the devDep verbatim. The devDep is a build-time
 * pin (`^0.2.0` - tight, for reproducible installs); the emitted peer range is
 * consumer-facing and must be the wide 0.x window `>=<floor> <1.0.0`, IDENTICAL
 * to vaultkit's peer range on core (`sdk/package.json`). WHY identical: the
 * single-physical-copy invariant (R3-2) - if a pack's peer range were narrower
 * (`^0.2.0` = `>=0.2.0 <0.3.0`) than vaultkit's, a consumer on a later 0.x core
 * that vaultkit accepts would fail the pack's peer or resolve a second core copy
 * (breaking cross-boundary `instanceof` + shared constants). So derive the floor
 * from the declared devDep and wrap it, keeping ONE declared source of truth.
 */
function resolveCorePeerVersion(): string {
	const rootPkgJsonPath = path.join(REPO_ROOT, "package.json");
	if (!existsSync(rootPkgJsonPath)) {
		fail(`missing ${rootPkgJsonPath}; cannot derive @newton-xyz/policy-core peer-dep range.`);
	}
	const pkg = readJson<{ devDependencies?: Record<string, string> }>(rootPkgJsonPath);
	const declared = pkg.devDependencies?.["@newton-xyz/policy-core"];
	if (!declared || typeof declared !== "string") {
		fail(
			`repo-root package.json declares no devDependencies["@newton-xyz/policy-core"]; cannot derive peer-dep range. Add it as the authoritative core version source.`,
		);
	}
	// Extract the semver floor (strip a leading `^`/`~`/`>=` etc), wrap as the
	// 0.x-wide consumer range. `^0.2.0` -> `>=0.2.0 <1.0.0`.
	const floor = declared.match(/\d+\.\d+\.\d+/)?.[0];
	if (!floor) {
		fail(
			`could not parse a semver floor from devDependencies["@newton-xyz/policy-core"] = "${declared}".`,
		);
	}
	return `>=${floor} <1.0.0`;
}

/**
 * The build-time devDep pin for `@newton-xyz/policy-core`, emitted verbatim into
 * each generated pack's `devDependencies` (a pack installs core from npm - core
 * is a different repo, NOT a workspace member - so this is `^0.2.0`, not
 * `workspace:*`). Reads the same authoritative root devDep as the peer range.
 */
function rootCoreDevRange(): string {
	const rootPkgJsonPath = path.join(REPO_ROOT, "package.json");
	const pkg = readJson<{ devDependencies?: Record<string, string> }>(rootPkgJsonPath);
	const declared = pkg.devDependencies?.["@newton-xyz/policy-core"];
	if (!declared || typeof declared !== "string") {
		fail(`repo-root package.json declares no devDependencies["@newton-xyz/policy-core"].`);
	}
	return declared;
}

interface DeploymentEntry {
	policyData: string;
	wasmCid: string;
	// Superseded wasmCids for this cell, recorded by sync-deployments.sh on
	// redeploy. Passed through verbatim into the generated `deployments.ts` so
	// the composite builder's historical-pin check can read each module's
	// attested cid history. Absent on never-redeployed cells.
	priorWasmCids?: string[];
	policyCodeHash: string;
	deployedAt: string;
}

type GatewayEnv = "stagef" | "prod";

interface DeploymentsFile {
	schemaVersion: number;
	comment?: string;
	chains: Record<string, string>;
	envs?: Record<GatewayEnv, string>;
	packs: Record<string, Record<string, Partial<Record<GatewayEnv, DeploymentEntry>>>>;
}

interface PackMetadata {
	name: string;
	version: string;
	author?: string;
	link?: string;
	description: string;
}

function fail(message: string): never {
	console.error(`generate-bindings: ${message}`);
	process.exit(1);
}

function readJson<T>(filePath: string): T {
	return JSON.parse(readFileSync(filePath, "utf8")) as T;
}

function writeFile(filePath: string, content: string): void {
	mkdirSync(path.dirname(filePath), { recursive: true });
	writeFileSync(filePath, content, "utf8");
}

/**
 * Walk a JSON Schema and report whether it admits a top-level `_manifest`
 * field by any path. Returns a human-readable description of the offending
 * branch, or `null` if the schema rejects `_manifest` everywhere.
 *
 * Why every branch matters: a pack author could dodge a naive
 * `properties._manifest` check by routing the field through `oneOf` /
 * `anyOf` / `allOf` / `patternProperties`, or by leaving the schema open
 * (no `additionalProperties: false`). Each of those would let an on-chain
 * `policyParams` blob carry a top-level `_manifest` collision with the
 * composite-manifest discriminator. The walker covers every JSON Schema
 * variant we've seen pack authors use.
 */
export function findManifestKeyViolation(schema: unknown): string | null {
	return walk(schema, "<root>");

	function walk(node: unknown, where: string): string | null {
		if (!node || typeof node !== "object" || Array.isArray(node)) return null;
		const s = node as Record<string, unknown>;

		// Direct property declaration.
		const props = s.properties as Record<string, unknown> | undefined;
		if (props && "_manifest" in props) {
			return `${where}.properties._manifest`;
		}

		// Pattern-based property that could match `_manifest`. JSON Schema's
		// `patternProperties` keys are ECMA-262 regexes — test each against
		// the literal string `_manifest`.
		const patternProps = s.patternProperties as Record<string, unknown> | undefined;
		if (patternProps) {
			for (const pattern of Object.keys(patternProps)) {
				try {
					if (new RegExp(pattern).test("_manifest")) {
						return `${where}.patternProperties[${JSON.stringify(pattern)}] matches "_manifest"`;
					}
				} catch {
					// Invalid regex in the schema — not our problem; let zod codegen
					// surface it later. Continue scanning other keys.
				}
			}
		}

		// Note: we deliberately do NOT flag schemas that lack
		// `additionalProperties: false`. Zod's `.strict()` injection at
		// emitSchemaFile time enforces "no additional keys" at the SDK boundary,
		// so an open JSON Schema can't actually admit `_manifest` at runtime —
		// the curator would get a parse error from the generated zod schema
		// before the bytes reach `setPolicy(...)`. Flagging open schemas here
		// would force every existing pack to add `additionalProperties: false`
		// (real partner-facing churn) for a guard the runtime already provides.
		// The walker focuses on EXPLICIT `_manifest` declarations.

		// Recurse into combinators.
		for (const combinator of ["oneOf", "anyOf", "allOf"] as const) {
			const branches = s[combinator] as ReadonlyArray<unknown> | undefined;
			if (Array.isArray(branches)) {
				for (let i = 0; i < branches.length; i++) {
					const found = walk(branches[i], `${where}.${combinator}[${i}]`);
					if (found) return found;
				}
			}
		}

		// `not` is the only other JSON Schema combinator that nests a subschema —
		// `not: { properties: { _manifest: ... } }` would *forbid* `_manifest`,
		// which is fine. We don't recurse into `not`.

		return null;
	}
}

/** Discover all pack directories at the repo root that have a complete set
 *  of schema files + metadata. Skips dotfiles, `packages/`, `scripts/`, and
 *  `node_modules/`. */
function discoverPacks(): string[] {
	const packs: string[] = [];
	const skip = new Set([
		"packages",
		"scripts",
		"node_modules",
		".changeset",
		".git",
		".github",
		"dist",
		"examples",
	]);
	for (const entry of readdirSync(REPO_ROOT, { withFileTypes: true })) {
		if (!entry.isDirectory()) continue;
		if (entry.name.startsWith(".")) continue;
		if (skip.has(entry.name)) continue;
		const packDir = path.join(REPO_ROOT, entry.name);
		const hasAllSchemas = SCHEMA_FILES.every((f) => existsSync(path.join(packDir, f)));
		const hasMetadata = existsSync(path.join(packDir, "policy_metadata.json"));
		if (hasAllSchemas && hasMetadata) packs.push(entry.name);
	}
	return packs.sort();
}

function jsLiteral(value: unknown): string {
	return JSON.stringify(value, null, 2);
}

function emitSchemaFile(
	zodName: string,
	typeName: string,
	schema: unknown,
	sourceRelPath: string,
): string {
	const inner = jsonSchemaToZod(schema as Parameters<typeof jsonSchemaToZod>[0]);
	// Top-level `ParamsSchema` rejects unknown keys at the SDK boundary so a
	// curator typo throws in `encodePolicyParams` rather than getting silently
	// stripped and shipping AVS-rejecting bytes. Nested objects inside `inner`
	// are unaffected — only the outer chain gains `.strict()`.
	const expr = zodName === "ParamsSchema" ? `${inner}.strict()` : inner;
	// `ParamsSchema` additionally ships the raw source JSON Schema as a
	// `ParamsJsonSchema` constant. This is the canonical inner schema a
	// composite manifest's pinned `policyParams` schema inlines under
	// `params.<shortId>` (see `generateCompositeParamsSchema`). Byte-derived
	// from the same `params_schema.json` the zod comes from, so the two can't
	// drift. The AVS-side `params_schema.json` only uses regorus-clean
	// keywords (type/properties/required/items/minimum/maximum/enum/…), so the
	// embedded literal is safe to validate the on-chain blob with directly.
	const jsonSchemaConst =
		zodName === "ParamsSchema"
			? `\nexport const ParamsJsonSchema = ${jsLiteral(schema)} as const;\n`
			: "";
	return `${BANNER}// Source schema: ${sourceRelPath}
import { z } from "zod";

export const ${zodName} = ${expr};

export type ${typeName} = z.infer<typeof ${zodName}>;
${jsonSchemaConst}`;
}

function emitMetadata(meta: PackMetadata): string {
	return `${BANNER}export const PACK_NAME = ${jsLiteral(meta.name)} as const;
export const PACK_VERSION = ${jsLiteral(meta.version)} as const;
export const PACK_DESCRIPTION = ${jsLiteral(meta.description)} as const;
export const PACK_LINK = ${jsLiteral(meta.link ?? "")} as const;
export const PACK_AUTHOR = ${jsLiteral(meta.author ?? "")} as const;
`;
}

/**
 * Gateway envs that may appear in PUBLISHED per-pack `deployments.ts`. `stagef`
 * is an internal-only staging env: it lives in the repo-root `deployments.json`
 * (the full audit trail) but must NOT ship in the npm packages or be referenced
 * in published docs. External SDK consumers only ever target `prod`.
 */
const PUBLISHED_ENVS: ReadonlySet<GatewayEnv> = new Set<GatewayEnv>(["prod"]);

/**
 * Drop internal-only env cells (`stagef`) from a pack's deployments before
 * emitting its published `deployments.ts`. A chain left with no published env
 * after filtering is dropped entirely (rather than emitting an empty `{}`),
 * so the generated map only lists chains that actually have a published
 * deployment. The repo-root `deployments.json` is untouched — it remains the
 * complete internal record including stagef.
 */
export function filterPublishedEnvs(
	perChain: Record<string, Partial<Record<GatewayEnv, DeploymentEntry>>>,
): Record<string, Partial<Record<GatewayEnv, DeploymentEntry>>> {
	const out: Record<string, Partial<Record<GatewayEnv, DeploymentEntry>>> = {};
	for (const [chainId, byEnv] of Object.entries(perChain)) {
		const publishedCells: Partial<Record<GatewayEnv, DeploymentEntry>> = {};
		for (const [env, entry] of Object.entries(byEnv) as [GatewayEnv, DeploymentEntry][]) {
			if (PUBLISHED_ENVS.has(env)) publishedCells[env] = entry;
		}
		if (Object.keys(publishedCells).length > 0) out[chainId] = publishedCells;
	}
	return out;
}

function emitDeployments(
	perChain: Record<string, Partial<Record<GatewayEnv, DeploymentEntry>>>,
): string {
	return `${BANNER}import type { ChainId, Deployment, GatewayEnv } from "@newton-xyz/policy-core";

export const deployments = ${jsLiteral(
		perChain,
	)} as const satisfies Readonly<Partial<Record<ChainId, Readonly<Partial<Record<GatewayEnv, Deployment>>>>>>;
`;
}

/**
 * Emit the registry package's audited-provenance map: first-party pack short id
 * -> chainId -> env -> policyData address, PROD ENV ONLY (filterPublishedEnvs).
 * Passed (with KNOWN_PACK_IDS) into `@newton-xyz/policy-core`'s classifyProvenance
 * to tell an audited pack from a lookalike. Lives INSIDE
 * `@newton-xyz/policy-pack-registry`: `ChainId`/`GatewayEnv` come from policy-core
 * (the types moved there); `KnownPackId` is the registry's own hand-authored
 * literal-union, imported relatively (importing the package specifier would be a
 * circular self-import on the very package this file lives in).
 */
function emitProvenance(packs: string[], deploymentsFile: DeploymentsFile): string {
	const map: Record<string, Record<string, Partial<Record<GatewayEnv, string>>>> = {};
	for (const packName of packs) {
		const perChain = filterPublishedEnvs(deploymentsFile.packs[packName] ?? {});
		const byChain: Record<string, Partial<Record<GatewayEnv, string>>> = {};
		for (const [chainId, byEnv] of Object.entries(perChain)) {
			const cell: Partial<Record<GatewayEnv, string>> = {};
			for (const [env, entry] of Object.entries(byEnv) as [GatewayEnv, DeploymentEntry][]) {
				cell[env] = entry.policyData;
			}
			byChain[chainId] = cell;
		}
		map[packName] = byChain;
	}
	return `${BANNER}import type { ChainId, GatewayEnv } from "@newton-xyz/policy-core";
import type { KnownPackId } from "./known-pack-ids";

export const AUDITED_POLICY_DATA = ${jsLiteral(
		map,
	)} as const satisfies Readonly<Record<KnownPackId, Readonly<Partial<Record<ChainId, Readonly<Partial<Record<GatewayEnv, string>>>>>>>>;
`;
}

function emitIndex(hasPackFile: boolean): string {
	const generatedReExports = `export * from "./wasm-args";
export * from "./secrets";
export * from "./params";
export * from "./deployments";
export * from "./metadata";
`;
	const packReExport = hasPackFile
		? `export * from "./pack";\n`
		: `// (no \`pack.ts\` yet — this pack ships generated bindings only. Add a hand-written \`pack.ts\`
// exporting a \`PolicyPack\` from \`@newton-xyz/policy-core\` to make it usable with createShield.)
`;
	return `${BANNER}${generatedReExports}${packReExport}`;
}

function emitPackageJson(packName: string, corePeerRange: string, coreDevRange: string): string {
	return `${jsLiteral({
		name: `@newton-xyz/policy-pack-${packName}`,
		version: "0.1.0",
		description: `Typed TypeScript bindings for the Newton ${packName} policy pack.`,
		license: "Apache-2.0",
		author: "Newton Protocol <https://x.com/newton_xyz> (https://newton.xyz)",
		homepage: `https://github.com/newt-foundation/newton-policy-packs/tree/main/packages/policy-pack-${packName}`,
		repository: {
			type: "git",
			url: "git+https://github.com/newt-foundation/newton-policy-packs.git",
			directory: `packages/policy-pack-${packName}`,
		},
		bugs: {
			url: "https://github.com/newt-foundation/newton-policy-packs/issues",
		},
		keywords: ["newton", "newton-protocol", "policy-pack", "shield", packName],
		publishConfig: { access: "public" },
		sideEffects: false,
		type: "module",
		main: "./dist/index.cjs",
		module: "./dist/index.js",
		types: "./dist/index.d.ts",
		exports: {
			".": {
				types: "./dist/index.d.ts",
				import: "./dist/index.js",
				require: "./dist/index.cjs",
			},
		},
		files: ["dist", "README.md", "LICENSE"],
		scripts: {
			build: "tsup",
			dev: "tsup --watch",
			typecheck: "tsc --noEmit",
			test: "echo 'no tests yet'",
		},
		peerDependencies: {
			"@newton-xyz/policy-core": corePeerRange,
			viem: "^2.0.0",
			zod: "^3.0.0",
		},
		devDependencies: {
			"@newton-xyz/policy-core": coreDevRange,
			tsup: "^8.5.1",
			typescript: "^5.5.0",
			viem: "^2.0.0",
			zod: "^3.23.0",
		},
	})}\n`;
}

function emitTsconfig(): string {
	return `${jsLiteral({
		extends: "../../tsconfig.base.json",
		compilerOptions: { outDir: "dist", rootDir: "src" },
		include: ["src/**/*"],
		exclude: ["dist", "node_modules"],
	})}\n`;
}

function emitTsupConfig(): string {
	return `import { defineConfig } from "tsup";

export default defineConfig({
\tentry: ["src/index.ts"],
\tformat: ["esm", "cjs"],
\tdts: true,
\tsourcemap: true,
\tclean: true,
\tplatform: "neutral",
\ttarget: "es2022",
\texternal: ["viem", "zod", "@newton-xyz/policy-core"],
});
`;
}

function emitPackReadme(packName: string, meta: PackMetadata): string {
	return `# \`@newton-xyz/policy-pack-${packName}\`

${meta.description}

Typed TypeScript bindings for the Newton **${packName}** policy pack. Generated from the AVS-side artifacts at [\`/${packName}/\`](../../${packName}/) in this repo.

## Install

\`\`\`bash
pnpm add @newton-xyz/policy-pack-${packName}
\`\`\`

## What's exported

| Export | Source | Purpose |
|---|---|---|
| \`WasmArgsSchema\` (zod) + \`WasmArgs\` (type) | \`wasm_args_schema.json\` | Inputs the pack's WASM receives at evaluation time. |
| \`SecretsSchema\` (zod) + \`Secrets\` (type) | \`secrets_schema.json\` | API credentials uploaded before run/sim. |
| \`ParamsSchema\` (zod) + \`Params\` (type) | \`params_schema.json\` | Configuration thresholds, set at policy upload time. |
| \`deployments\` | top-level \`deployments.json\` | \`chainId → env → { policyData, wasmCid, priorWasmCids?, policyCodeHash, deployedAt }\` (env keys: \`stagef\`, \`prod\`) — the reusable oracle; curators deploy their own policy referencing it |
| \`PACK_NAME\`, \`PACK_VERSION\`, \`PACK_DESCRIPTION\`, \`PACK_LINK\`, \`PACK_AUTHOR\` | \`policy_metadata.json\` | Static pack identity. |

## Regeneration

The \`src/*\` files are generated. Edit the upstream JSON schemas under [\`/${packName}/\`](../../${packName}/) and run \`pnpm gen:bindings\` from the repo root to regenerate.

The \`package.json\`, \`tsconfig.json\`, \`tsup.config.ts\`, and this README are scaffolded once and not overwritten on regen — you can hand-tune them.
`;
}

/**
 * Umbrella package wiring (`@newton-xyz/policy-packs`). The per-pack
 * packages are `private`; only the umbrella publishes, bundling every pack
 * behind one subpath export per pack. Everything in the umbrella that
 * depends on the pack list is derived here from the discovered packs, so a
 * new pack joins the umbrella on the next `pnpm gen:bindings` with no
 * hand-editing: `src/<name>.ts` re-export modules, the `src/index.ts`
 * namespace exports, the `tsup.config.ts` entry list, and the
 * `package.json` `exports` subpaths + `workspace:*` devDependencies.
 * Hand-maintained `package.json` fields (version, scripts, peerDeps, …)
 * are preserved verbatim — codegen owns only the wiring.
 */
export function emitUmbrellaPackModule(packName: string): string {
	return `${BANNER}// Umbrella re-export for the ${packName} policy pack. The pack package itself is
// private; its code is bundled into @newton-xyz/policy-packs at build time.
export * from "@newton-xyz/policy-pack-${packName}";
`;
}

export function emitUmbrellaIndex(packs: string[]): string {
	const lines = packs.map((p) => `export * as ${p} from "./${p}";`).join("\n");
	return `${BANNER}// @newton-xyz/policy-packs: every Newton policy pack in one package.
//
// Import a single pack from its subpath, e.g.
//   import { ... } from "@newton-xyz/policy-packs/webacy";
// or pull a pack in as a namespace from the root entry, as below.

${lines}
`;
}

export function emitUmbrellaTsupConfig(packs: string[]): string {
	const entries = ["src/index.ts", ...packs.map((p) => `src/${p}.ts`)]
		.map((e) => `\t\t"${e}",`)
		.join("\n");
	return `import { defineConfig } from "tsup";

export default defineConfig({
\tentry: [
${entries}
\t],
\tformat: ["esm", "cjs"],
\tdts: true,
\tsourcemap: true,
\tclean: true,
\tplatform: "neutral",
\ttarget: "es2022",
\texternal: ["viem", "zod", "@newton-xyz/policy-core"],
});
`;
}

interface UmbrellaPackageJson {
	exports?: Record<string, unknown>;
	devDependencies?: Record<string, string>;
	[key: string]: unknown;
}

/**
 * Rebuild the codegen-owned parts of the umbrella `package.json` for the
 * given pack list: `exports` ("." first — preserved verbatim if present —
 * then one subpath per pack, then any other hand-added export keys in
 * their existing order) and the `@newton-xyz/policy-pack-*` entries of
 * `devDependencies` (one `workspace:*` per pack, first; every non-pack
 * entry follows in its existing order). A stale pack subpath — a
 * single-segment `./<name>` key whose value is exactly the generated
 * entry shape for that name — drops out; a hand-added subpath with any
 * other shape is preserved. Everything else in the file is returned
 * untouched.
 */
export function updateUmbrellaPackageJson(
	pkg: UmbrellaPackageJson,
	packs: string[],
): UmbrellaPackageJson {
	const existingExports = pkg.exports ?? {};
	const exports: Record<string, unknown> = {};
	if ("." in existingExports) {
		exports["."] = existingExports["."];
	} else {
		exports["."] = {
			types: "./dist/index.d.ts",
			import: "./dist/index.js",
			require: "./dist/index.cjs",
		};
	}
	for (const p of packs) {
		exports[`./${p}`] = {
			types: `./dist/${p}.d.ts`,
			import: `./dist/${p}.js`,
			require: `./dist/${p}.cjs`,
		};
	}
	for (const [key, value] of Object.entries(existingExports)) {
		if (key === "." || packs.some((p) => key === `./${p}`)) continue;
		// Drop stale pack subpaths (removed packs): single-segment key whose
		// value is exactly the generated entry shape for that name. Any other
		// hand-added subpath is preserved.
		const stalePack = key.match(/^\.\/([a-z0-9_]+)$/)?.[1];
		if (
			stalePack &&
			JSON.stringify(value) ===
				JSON.stringify({
					types: `./dist/${stalePack}.d.ts`,
					import: `./dist/${stalePack}.js`,
					require: `./dist/${stalePack}.cjs`,
				})
		) {
			continue;
		}
		exports[key] = value;
	}
	const existingDev = pkg.devDependencies ?? {};
	const devDependencies: Record<string, string> = {};
	for (const p of packs) {
		devDependencies[`@newton-xyz/policy-pack-${p}`] = "workspace:*";
	}
	for (const [key, value] of Object.entries(existingDev)) {
		if (key.startsWith("@newton-xyz/policy-pack-")) continue;
		devDependencies[key] = value;
	}
	return { ...pkg, exports, devDependencies };
}

function emitUmbrella(packs: string[]): void {
	const pkgJsonPath = path.join(UMBRELLA_PACKAGE_DIR, "package.json");
	if (!existsSync(pkgJsonPath)) {
		fail(
			`missing ${pkgJsonPath}; the @newton-xyz/policy-packs umbrella package must exist (see packages/README.md).`,
		);
	}
	const srcDir = path.join(UMBRELLA_PACKAGE_DIR, "src");
	mkdirSync(srcDir, { recursive: true });
	// Remove wiring for packs that no longer exist. Only files carrying the
	// generated re-export shape are touched — anything hand-written survives.
	for (const entry of readdirSync(srcDir)) {
		if (!entry.endsWith(".ts") || entry === "index.ts") continue;
		const packName = entry.slice(0, -".ts".length);
		if (packs.includes(packName)) continue;
		const filePath = path.join(srcDir, entry);
		if (readFileSync(filePath, "utf8").includes('from "@newton-xyz/policy-pack-')) {
			rmSync(filePath);
		}
	}
	for (const packName of packs) {
		writeFile(path.join(srcDir, `${packName}.ts`), emitUmbrellaPackModule(packName));
	}
	writeFile(path.join(srcDir, "index.ts"), emitUmbrellaIndex(packs));
	writeFile(path.join(UMBRELLA_PACKAGE_DIR, "tsup.config.ts"), emitUmbrellaTsupConfig(packs));
	const pkg = readJson<UmbrellaPackageJson>(pkgJsonPath);
	writeFile(pkgJsonPath, `${JSON.stringify(updateUmbrellaPackageJson(pkg, packs), null, "\t")}\n`);
}

function camel(s: string): string {
	return s.replace(/[-_](\w)/g, (_, c) => c.toUpperCase());
}

function main(): void {
	const deploymentsPath = path.join(REPO_ROOT, "deployments.json");
	if (!existsSync(deploymentsPath)) {
		fail(`missing deployments.json at ${deploymentsPath}`);
	}
	const deploymentsFile = readJson<DeploymentsFile>(deploymentsPath);

	const corePeerRange = resolveCorePeerVersion();
	const coreDevRange = rootCoreDevRange();
	console.log(`generate-bindings: @newton-xyz/policy-core peer range = ${corePeerRange}`);

	const packs = discoverPacks();
	if (packs.length === 0) {
		fail(`no packs discovered at ${REPO_ROOT}`);
	}
	console.log(`generate-bindings: discovered ${packs.length} pack(s):`);
	for (const p of packs) console.log(`  - ${p}`);

	// Cross-check the discovered pack list against KNOWN_PACK_IDS. The registry
	// in @newton-xyz/policy-pack-registry MUST list every published pack's short
	// id; defineComposite (Phase 2, in @newton-xyz/policy-core) rejects modules
	// whose short id isn't there. A pack PR that adds the directory + schemas but
	// forgets to update the registry would deploy code that no composite could
	// consume.
	//
	// We don't import the registry from policy-pack-registry at codegen time
	// (avoid a build-time circular dep: the codegen WRITES the provenance file into
	// that same package). Instead, parse the `KNOWN_PACK_IDS = [...] as const
	// satisfies ...` literal out of the source file directly.
	const knownIdsSrc = readFileSync(
		path.join(REGISTRY_PACKAGE_DIR, "src/known-pack-ids.ts"),
		"utf8",
	);
	// Match `[...]` after `KNOWN_PACK_IDS =`. Permissive about what follows
	// the closing `]` (biome may reformat `as const satisfies ...` onto a
	// new line; trailing-syntax matters less than the array contents).
	const knownIdsMatch = knownIdsSrc.match(/export const KNOWN_PACK_IDS = \[([\s\S]*?)\]/);
	if (!knownIdsMatch) {
		fail(
			"could not parse KNOWN_PACK_IDS from policy-pack-registry/src/known-pack-ids.ts — registry shape changed?",
		);
	}
	// Strip line + block comments BEFORE extracting quoted strings. A comment
	// like `// TODO add "newpack"` inside the array would otherwise look like
	// a registered entry to the parser even though the runtime literal doesn't
	// include it.
	// biome-ignore lint/style/noNonNullAssertion: regex matched above
	const registryBody = knownIdsMatch[1]!.replace(/\/\/.*$/gm, "").replace(/\/\*[\s\S]*?\*\//g, "");
	const registry = new Set(Array.from(registryBody.matchAll(/"([^"]+)"/g), (m) => m[1] as string));
	const discoveredSet = new Set(packs);
	const missingFromRegistry = [...discoveredSet].filter((p) => !registry.has(p));
	const stalRegistryEntries = [...registry].filter((p) => !discoveredSet.has(p));
	if (missingFromRegistry.length || stalRegistryEntries.length) {
		const lines = [
			"KNOWN_PACK_IDS registry drift detected — Phase 2 composite verification depends on it.",
		];
		if (missingFromRegistry.length) {
			lines.push(
				`  Missing from registry (add these to policy-pack-registry/src/known-pack-ids.ts): ${missingFromRegistry.map((p) => `"${p}"`).join(", ")}`,
			);
		}
		if (stalRegistryEntries.length) {
			lines.push(
				`  Stale registry entries (no matching pack directory at repo root): ${stalRegistryEntries.map((p) => `"${p}"`).join(", ")}`,
			);
		}
		fail(lines.join("\n"));
	}

	for (const packName of packs) {
		const packSrcDir = path.join(REPO_ROOT, packName);
		const packageDir = path.join(PACKAGES_DIR, `policy-pack-${packName}`);
		const srcDir = path.join(packageDir, "src");

		// Regenerate generated files only. Hand-written files in `src/` (e.g.
		// `pack.ts` exporting the canonical `PolicyPack` object, or
		// `prepare-query.ts` reading on-chain state) survive regen — only the
		// 6 files this script owns are wiped, not the whole `src/` directory.
		mkdirSync(srcDir, { recursive: true });
		const GENERATED_FILES = [
			"wasm-args.ts",
			"secrets.ts",
			"params.ts",
			"metadata.ts",
			"deployments.ts",
			"index.ts",
		] as const;
		for (const f of GENERATED_FILES) {
			const p = path.join(srcDir, f);
			if (existsSync(p)) rmSync(p);
		}

		const wasmArgsSchema = readJson<unknown>(path.join(packSrcDir, "wasm_args_schema.json"));
		const secretsSchema = readJson<unknown>(path.join(packSrcDir, "secrets_schema.json"));
		const paramsSchema = readJson<unknown>(path.join(packSrcDir, "params_schema.json"));
		// `_manifest` is reserved for the composite-policy manifest discriminator
		// (NEWT-1541, see `docs/composite-manifest-spec.md`). A pack declaring
		// `_manifest` at the top level of `params_schema.json` would collide with
		// the discriminator and break depositor verification. Codegen rejects it
		// here so the violation surfaces at PR time, not at production
		// `decodeManifest(...)` time.
		//
		// We walk every variant a JSON Schema can use to admit a top-level
		// `_manifest` field — direct `properties`, branch composites
		// (`oneOf`/`anyOf`/`allOf`), `patternProperties` (which can match
		// `_manifest` via regex), and a fully-open object (no
		// `additionalProperties: false`). Each branch is checked by a recursive
		// walker so nested combinators don't slip through.
		const violation = findManifestKeyViolation(paramsSchema);
		if (violation) {
			fail(
				`pack \`${packName}\` admits a top-level \`_manifest\` property in params_schema.json (${violation}) — that key is reserved for the composite-policy manifest discriminator (see docs/composite-manifest-spec.md). Tighten the schema or rename the property.`,
			);
		}
		const meta = readJson<PackMetadata>(path.join(packSrcDir, "policy_metadata.json"));

		writeFile(
			path.join(srcDir, "wasm-args.ts"),
			emitSchemaFile(
				"WasmArgsSchema",
				"WasmArgs",
				wasmArgsSchema,
				`${packName}/wasm_args_schema.json`,
			),
		);
		writeFile(
			path.join(srcDir, "secrets.ts"),
			emitSchemaFile("SecretsSchema", "Secrets", secretsSchema, `${packName}/secrets_schema.json`),
		);
		writeFile(
			path.join(srcDir, "params.ts"),
			emitSchemaFile("ParamsSchema", "Params", paramsSchema, `${packName}/params_schema.json`),
		);
		writeFile(path.join(srcDir, "metadata.ts"), emitMetadata(meta));

		const perChain = filterPublishedEnvs(deploymentsFile.packs[packName] ?? {});
		writeFile(path.join(srcDir, "deployments.ts"), emitDeployments(perChain));

		// Re-export hand-written `pack.ts` if the maintainer has provided one.
		const packFilePath = path.join(srcDir, "pack.ts");
		const hasPackFile = existsSync(packFilePath);
		writeFile(path.join(srcDir, "index.ts"), emitIndex(hasPackFile));

		// Scaffold once. Don't overwrite if the pack maintainer has hand-tuned.
		const pkgJsonPath = path.join(packageDir, "package.json");
		if (!existsSync(pkgJsonPath)) {
			writeFile(pkgJsonPath, emitPackageJson(packName, corePeerRange, coreDevRange));
		}
		const tsconfigPath = path.join(packageDir, "tsconfig.json");
		if (!existsSync(tsconfigPath)) {
			writeFile(tsconfigPath, emitTsconfig());
		}
		const tsupConfigPath = path.join(packageDir, "tsup.config.ts");
		if (!existsSync(tsupConfigPath)) {
			writeFile(tsupConfigPath, emitTsupConfig());
		}
		const readmePath = path.join(packageDir, "README.md");
		if (!existsSync(readmePath)) {
			writeFile(readmePath, emitPackReadme(packName, meta));
		}

		console.log(`  ✓ ${packName} → packages/policy-pack-${packName}/`);
	}

	writeFile(
		path.join(REGISTRY_PACKAGE_DIR, "src/known-pack-provenance.generated.ts"),
		emitProvenance(packs, deploymentsFile),
	);
	console.log(
		"  provenance -> packages/policy-pack-registry/src/known-pack-provenance.generated.ts",
	);

	emitUmbrella(packs);
	console.log(
		"  umbrella -> packages/policy-packs/ (src modules, index, tsup entries, package.json wiring)",
	);

	// Formatting is the responsibility of `pnpm lint:fix`, not codegen. The
	// previous in-codegen biome call swallowed errors and could silently emit
	// unformatted files in environments without `pnpm` (e.g. fresh CI containers
	// before devDeps install). Decoupling avoids that footgun.

	// Suppress unused-import warnings while keeping the helper available for
	// future per-pack name-mangling needs (e.g. discriminated unions).
	void camel;

	console.log("\ngenerate-bindings: done.");
	console.log("  Next: `pnpm install && pnpm lint:fix && pnpm -r typecheck && pnpm -r build`.");
}

// Only auto-execute when run as a script (e.g. `pnpm gen:bindings`), NOT when
// imported by a test (e.g. `findManifestKeyViolation` self-test). `pathToFileURL`
// handles Windows backslashes and spaces in paths, which a manual
// `file://${argv[1]}` concatenation would mangle.
if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
	main();
}
